let aiOutput;
try {
  const raw = $input.first().json;
  // Handle both direct JSON and OpenAI response structure
  let content = raw.message?.content || raw.choices?.[0]?.message?.content || raw.response || JSON.stringify(raw);
  if (typeof content === 'string') {
    // Extract JSON from markdown code blocks if present
    const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
    if (jsonMatch) content = jsonMatch[1];
    aiOutput = JSON.parse(content);
  } else {
    aiOutput = content;
  }
} catch (e) {
  throw new Error(`AI JSON parsing failed: ${e.message}`);
}

// Validate score
if (typeof aiOutput.qualification_score !== 'number' || aiOutput.qualification_score < 0 || aiOutput.qualification_score > 100) {
  throw new Error(`Invalid score: ${aiOutput.qualification_score}`);
}

// Validate temperature corresponds to score
let expectedTemp = 'COLD';
if (aiOutput.qualification_score >= 80) expectedTemp = 'HOT';
else if (aiOutput.qualification_score >= 50) expectedTemp = 'WARM';

if (aiOutput.lead_temperature !== expectedTemp) {
  aiOutput.lead_temperature = expectedTemp; // Auto-correct
  aiOutput._temperature_corrected = true;
}

// Validate required fields
const required = ['business_need','lead_intent','urgency','qualification_score','lead_temperature','recommended_action','reasoning','sales_message'];
for (const field of required) {
  if (aiOutput[field] === undefined) throw new Error(`Missing required field: ${field}`);
}

return [{ json: { ...$input.first().json, ...aiOutput, ai_processed_at: new Date().toISOString() } }];

// Fallback scoring when AI fails
const lead = $input.first().json;
let score = 0;
if (lead.budget.includes('$50k')) score += 35;
else if (lead.budget.includes('$15k')) score += 28;
else if (lead.budget.includes('$5k')) score += 20;
else if (lead.budget.includes('$1k')) score += 10;
else score += 5;
score += lead.is_business_email ? 8 : 0;
score += lead.website ? 5 : 0;
score += lead.message && lead.message.length > 50 ? 7 : 0;
let temp = 'COLD';
if (score >= 80) temp = 'HOT';
else if (score >= 50) temp = 'WARM';
return [{ json: { ...lead, business_need: 'Other', lead_intent: 'Researching', urgency: 'Low', qualification_score: score, lead_temperature: temp, recommended_action: 'Manual review required - AI failed', reasoning: `Fallback scoring: ${score}`, sales_message: `Hi ${lead.name}, thanks for reaching out - we'll review and get back shortly.`, ai_fallback: true } }];
